// Power of 9: the in-game hot list (most collected), the server-wide Power of 9 meter and
// boost, 9-streaks, every-9-levels perks and the 589 m "manifesting" moments.
// Pure logic shared by the server (TrenchRoom + Pulse DO) and the browser (window.BTPower9,
// generated by tools/gen-shared.mjs). No imports, no Durable Object APIs.

export const P9 = {
  METER_MAX: 99,            // meter points per charge (env P9_METER_MAX may override, 9..9999)
  BOOST_MS: 99_000,         // POWER OF 9 boost length
  BOOST_BONUS_XP: 9,        // extra server XP per collectible while the boost runs
  BOOST_XP_CAP: 400,        // per-minute XP cap while the boost runs (normal: 250)
  BOOST_GEM_X: 1.09,        // client run multiplier per gem during the boost (normal 1.05)
  STREAK_N: 9,              // collectibles in a row ...
  STREAK_GAP_MS: 12_000,    // ... each within this long of the previous one
  PERK_EVERY: 9,            // a perk every 9 profile levels
  PERK_MAX_TIER: 5,
  MANIFEST_M: 589,          // one level band; crossing each multiple is a "manifesting" moment
  BUCKET_MS: 5 * 60_000,    // hot-list counts are kept in 5-minute buckets for 24 h
  FEED_MAX: 40,
  FLUSH_MS: 10_000,         // rooms batch their notes to the Pulse DO at most this often
  HEARTBEAT_MS: 30_000,     // ... and check in this often while humans are connected
  MAX_KEYS_PER_BATCH: 24,
  MAX_PLAYERS_PER_BATCH: 60,
  MAX_FEED_PER_BATCH: 8,
  MAX_COUNT_PER_KEY: 400,   // per 10 s batch; validated pickups are already rate-capped per session
  MAX_POINTS_PER_BATCH: 2000
};

// Meter points for server-validated actions.
export const P9_POINTS = { diamond: 1, power: 3, relic: 3, bossKill: 27, streak: 9, manifest: 9, perk: 9 };

export const COLLECTIBLE_KINDS = ['diamond', 'power', 'relic'];

export function meterMax(env) {
  const n = Math.floor(Number(env && env.P9_METER_MAX));
  return Number.isFinite(n) && n >= 9 && n <= 9999 ? n : P9.METER_MAX;
}

export function sanitizeTicker(t) {
  const s = String(t == null ? '' : t).trim().replace(/^\$/, '').toUpperCase();
  return /^[A-Z0-9]{1,12}$/.test(s) ? s : null;
}

/**
 * Hot-list key for a validated pickup. Power gems sit in seams named after coins on the
 * Telegram hot list; the ticker only counts when it is on the list the server fetched from
 * the bot (allow), otherwise it is filed as a plain POWER GEM so nobody can promote a coin
 * by naming it.
 */
export function collectibleKey(kind, ticker, allow) {
  if (kind === 'diamond') return 'GEM';
  if (kind === 'relic') return 'RELIC';
  if (kind === 'power') {
    const t = sanitizeTicker(ticker);
    return t && allow && (allow.has ? allow.has(t) : allow.includes(t)) ? '$' + t : 'POWER GEM';
  }
  return null;
}

export function keyLabel(key) {
  return key === 'GEM' ? 'GEM' : key === 'RELIC' ? 'RELIC' : key === 'POWER GEM' ? 'POWER GEM' : String(key);
}

/** 9-streak: collectibles in a row, each within STREAK_GAP_MS. Returns { st, hit }. */
export function noteStreak(st, now) {
  const s = st && now - st.t <= P9.STREAK_GAP_MS ? { n: st.n + 1, t: now } : { n: 1, t: now };
  return { st: s, hit: s.n % P9.STREAK_N === 0 };
}

export function perkTier(level) {
  return Math.max(0, Math.min(P9.PERK_MAX_TIER, Math.floor((Number(level) || 0) / P9.PERK_EVERY)));
}

/** The perk a profile level carries: +3% dig speed per 9 levels (max +15% at level 45). */
export function perkFor(level) {
  const tier = perkTier(level);
  return { tier, digSpeed: 1 + 0.03 * tier, label: tier ? `POWER OF 9 PERK ${tier}: +${3 * tier}% DIG SPEED` : '' };
}

/** New perk tier reached when the level goes from `from` to `to` (0 when none). */
export function perkCrossed(from, to) {
  const a = perkTier(from), b = perkTier(to);
  return b > a ? b : 0;
}

/** Highest multiple of 589 m crossed going from prevBest to newBest (0 when none). */
export function manifestCrossed(prevBest, newBest) {
  const a = Math.floor(Math.max(0, Number(prevBest) || 0) / P9.MANIFEST_M);
  const b = Math.floor(Math.max(0, Number(newBest) || 0) / P9.MANIFEST_M);
  return b > a ? b * P9.MANIFEST_M : 0;
}

export function bucketOf(now) { return Math.floor(now / P9.BUCKET_MS); }

export function periodKeys(now) {
  const d = new Date(now);
  const day = d.toISOString().slice(0, 10);
  // ISO week: Thursday of this week decides the year.
  const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const dow = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - dow);
  const y0 = new Date(Date.UTC(t.getUTCFullYear(), 0, 1));
  const wk = Math.ceil(((t - y0) / 86400000 + 1) / 7);
  return { day: 'd:' + day, week: 'w:' + t.getUTCFullYear() + '-W' + String(wk).padStart(2, '0'), all: 'all' };
}

export function isGuestId(id) { return typeof id === 'string' && id.startsWith('guest:'); }

/** Public name for feeds and boards: guests are anonymous. */
export function publicName(name, handle, guest) {
  if (guest) return 'anon trencher';
  if (handle && /^@[A-Za-z0-9_]{1,15}$/.test(handle)) return handle;
  const n = String(name || '').replace(/[^\w .#-]/g, '').trim().slice(0, 20);
  return n || 'trencher';
}

/** One Telegram-style line for a feed item (server stores items, clients format them). */
export function feedText(it) {
  if (!it || typeof it !== 'object') return '';
  const who = it.who || 'trencher';
  const at = Number.isFinite(it.depth) && it.depth > 0 ? ` at ${it.depth} m` : '';
  switch (it.kind) {
    case 'dig': return `${who} dug up ${it.n > 1 ? it.n + 'x ' : ''}${keyLabel(it.key)}${at}`;
    case 'streak': return `${who} hit a 9-STREAK${at} · +${P9_POINTS.streak} POWER`;
    case 'boss': return `${who} took down ${it.boss || 'the boss'}${at}`;
    case 'manifest': return `${who} is MANIFESTING ${it.depth} m · 589x`;
    case 'perk': return `${who} reached LEVEL ${it.level} · POWER OF 9 PERK ${it.tier}`;
    case 'boost': return `POWER OF 9 UNLOCKED · ${Math.round(P9.BOOST_MS / 1000)}s BOOST FOR EVERYONE ONLINE`;
    default: return '';
  }
}

/** Sum bucket maps ({bucket: {key: n}}) into a sorted list over the last `ms`. */
export function topKeys(buckets, now, ms, limit = 12) {
  const from = bucketOf(now - ms + P9.BUCKET_MS);
  const tot = {};
  for (const [b, m] of Object.entries(buckets || {})) {
    if (Number(b) < from) continue;
    for (const [k, n] of Object.entries(m)) tot[k] = (tot[k] || 0) + n;
  }
  return sortCounts(tot, limit);
}

export function sortCounts(tot, limit = 12) {
  return Object.entries(tot || {}).filter(([, n]) => n > 0)
    .sort((a, b) => b[1] - a[1] || (a[0] < b[0] ? -1 : 1)).slice(0, limit).map(([key, n]) => ({ key, n }));
}

export function boostActive(boost, now) {
  return !!(boost && now < boost.until);
}

/**
 * Add points to the meter. When it fills, a boost starts for everyone online and the meter
 * restarts with the overflow. Returns { meter, boost, fired }.
 */
export function chargeMeter({ meter, max, boost }, points, now) {
  let m = Math.max(0, Math.floor(Number(meter) || 0)) + Math.max(0, Math.floor(Number(points) || 0));
  let fired = null;
  if (m >= max) {
    const start = boostActive(boost, now) ? boost.until : now; // a boost during a boost queues after it
    fired = { id: Math.floor(now / 1000), start, until: start + P9.BOOST_MS };
    m = Math.min(m - max, Math.floor(max / 3)); // carry a little overflow, never a near-full meter
  }
  return { meter: m, boost: fired || boost || null, fired: !!fired };
}

export const LB_METRICS = ['depth', 'gems', 'boss', 'p9'];

/** Merge one player's batch into a board row. depth = max, the rest add up. */
export function mergeRow(row, add) {
  const r = row ? { ...row } : { name: add.name, depth: 0, gems: 0, boss: 0, p9: 0 };
  r.name = add.name || r.name;
  r.depth = Math.max(r.depth || 0, Math.floor(Number(add.depth) || 0));
  for (const k of ['gems', 'boss', 'p9']) r[k] = (r[k] || 0) + Math.max(0, Math.floor(Number(add[k]) || 0));
  return r;
}

export function rankRows(rows, metric, limit = 25) {
  const m = LB_METRICS.includes(metric) ? metric : 'p9';
  return rows.filter(r => (r[m] || 0) > 0)
    .sort((a, b) => (b[m] || 0) - (a[m] || 0) || (b.p9 || 0) - (a.p9 || 0) || (a.id < b.id ? -1 : 1))
    .slice(0, limit);
}
